import sys
from common import Failure, resource

COMMANDS = ['init-config','init','generate','build','parse','test','version','fuzz','query','highlight','tags','playground','dump-languages','complete']
ALIASES = {'g':'generate','b':'build','p':'parse','t':'test','q':'query','hi':'highlight'}
# A specification is (long spelling, short spelling, value name, validation).
def flag(name, short=None): return (name,short,None,None)
def val(name, short=None, label=None, kind=None): return (name,short,label or name.upper().replace('-','_'),kind)
G = val('grammar-path','p'); L=val('lib-path','l'); N=val('lang-name'); C=val('config-path'); S=val('scope'); P=val('paths',None,'PATHS_FILE'); R=flag('rebuild','r'); TN=val('test-number','n',kind='uint'); TIME=flag('time','t'); QUIET=flag('quiet','q'); ENC=val('encoding',kind=['utf8','utf16-le','utf16-be'])
SPECS={
'init-config':[],
'init':[flag('update','u'),G],
'generate':[flag('log','l'),val('abi',label='VERSION'),flag('no-parser'),flag('build','b'),flag('debug-build','0'),val('libdir',label='PATH'),val('output','o','DIRECTORY'),val('report-states-for-rule'),flag('json'),flag('json-summary'),val('js-runtime',label='EXECUTABLE'),flag('disable-optimizations')],
'build':[flag('wasm','w'),val('output','o'),flag('reuse-allocator'),flag('debug','0'),flag('verbose','v')],
'parse':[P,G,L,N,S,val('debug','d',kind=['quiet','normal','pretty']),flag('debug-build','0'),flag('debug-graph','D'),flag('dot'),flag('xml','x'),flag('cst','c'),flag('stat','s'),val('timeout',kind='uint'),TIME,QUIET,val('edits',kind='multi'),ENC,flag('open-log'),flag('json'),flag('json-summary','j'),C,TN,R,flag('no-ranges')],
 'test':[val('include','i'),val('exclude','e'),val('file-name'),G,L,N,flag('update','u'),flag('debug','d'),flag('debug-build','0'),flag('debug-graph','D'),flag('open-log'),C,flag('show-fields'),val('stat',kind=['all','outliers-and-total','total-only']),R,flag('overview-only'),flag('json-summary')],
 'version':[G,val('bump',kind=['patch','minor','major'])],
 'fuzz':[val('skip','s'),val('subdir'),G,val('lib-path'),N,val('edits',kind='uint'),val('iterations',kind='uint'),val('include','i'),val('exclude','e'),flag('log-graphs'),flag('log','l'),R],
 'query':[G,L,N,TIME,QUIET,P,val('byte-range'),val('row-range'),val('containing-byte-range'),val('containing-row-range'),S,flag('captures','c'),flag('test'),C,TN,R],
 'highlight':[flag('html','H'),flag('css-classes'),flag('check'),val('captures-path'),val('query-paths',kind='multi'),S,TIME,QUIET,P,G,C,TN,R,ENC],
 'tags':[S,TIME,QUIET,P,G,C,TN,R],
 'playground':[QUIET,val('grammar-path'),val('export','e')],
 'dump-languages':[C],
 'complete':[val('shell','s',kind=['bash','elvish','fish','power-shell','zsh','nushell'])],
}
POSITIONAL={'generate':'[GRAMMAR_PATH]','build':'[PATH]','parse':'[PATHS]...','query':'<QUERY_PATH> [PATHS]...','highlight':'[PATHS]...','tags':'[PATHS]...','version':'[VERSION]'}
TAIL="For more information, try '--help'.\n"

def exe_name():
    return os.path.basename(sys.argv[0]) if '__main__' not in sys.argv[0] and sys.argv[0].endswith('executable') else 'executable'

def help_text(cmd='', short=False):
    file=(cmd or 'main')+('-short-help.txt' if cmd=='version' and short else '-help.txt')
    text=resource('help/'+file).replace('Usage: executable','Usage: '+exe_name())
    if cmd=='generate':
        for name in ['TREE_SITTER_ABI_VERSION','TREE_SITTER_JS_RUNTIME']:
            text=text.replace(name+'=]',name+'='+os.environ.get(name,'')+']')
    return text

def usage(cmd, extra=None):
    if not cmd:return exe_name()+' <COMMAND>'
    if extra is not None:return exe_name()+' '+cmd+(' '+extra if extra else '')
    return next(x[7:] for x in help_text(cmd).splitlines() if x.startswith('Usage: '))

def clierror(s, cmd=None, tip=None, use_usage=True, usage_extra=None):
    text='error: '+s+'\n'
    if tip:text+='\n  tip: '+tip+'\n'
    if use_usage:text+='\nUsage: '+usage(cmd,usage_extra)+'\n'
    text+='\n'+TAIL
    raise Failure(text,code=2,raw=True)

def desc(spec, cmd=None):
    n,s,v,k=spec
    if not v:return '--'+n
    if cmd=='parse' and n=='debug':return '--debug [<DEBUG>]'
    return '--'+n+' <'+v+'>'+('...' if k=='multi' else '')

def invalid(v, spec, cmd):
    n,s,label,k=spec
    d=desc(spec,cmd)
    if isinstance(k,list) and v not in k:
        text=f"error: invalid value '{v}' for '{d}'\n  [possible values: {', '.join(k)}]\n"
        similar=difflib.get_close_matches(v,k,n=1,cutoff=.65)
        if similar:text+=f"\n  tip: a similar value exists: '{similar[0]}'\n"
