"""Shared I/O, diagnostics, and JSON helpers."""
import json
import os
import pathlib
import sys
import zipfile

class Failure(Exception):
    def __init__(self, message, causes=None, code=1, raw=False):
        self.message = message
        self.causes = causes or []
        self.code = code
        self.raw = raw

def resource(name):
    try:
        with zipfile.ZipFile(sys.argv[0]) as z:
            return z.read('resources/' + name).decode()
    except (OSError, zipfile.BadZipFile):
        return (pathlib.Path(__file__).resolve().parent.parent / 'resources' / name).read_text()

def out(s):
    sys.stdout.write(s)

def err(s):
    sys.stderr.write(s)

def warning(s):
    err('\x1b[33mWarning:\x1b[0m ' + s + '\n')

def report_failure(e):
    if e.raw:
        err(e.message)
        return
    err('\x1b[31mError:\x1b[0m ' + e.message + '\n')
    if e.causes:
        err('\nCaused by:\n')
        for i, c in enumerate(e.causes):
            prefix = '    ' if len(e.causes) == 1 else '    %d: ' % i
            parts = str(c).split('\n')
            err(prefix + parts[0] + '\n')
            for part in parts[1:]:
                err('    ' + part + '\n')

def os_error(exc):
    n = getattr(exc, 'errno', 2) or 2
    names = {2:'No such file or directory', 13:'Permission denied', 20:'Not a directory', 21:'Is a directory', 17:'File exists', 22:'Invalid argument'}
    return f'{names.get(n, os.strerror(n))} (os error {n})'

def read_text(path):
    try:
        return pathlib.Path(path).read_text()
    except OSError as e:
        raise Failure(os_error(e))

def json_error(e, text):
    pos, msg = e.pos, e.msg
    if msg.startswith('Expecting property name'):
        m = 'key must be a string'
        if pos < len(text) and text[pos] == '}':
            m = 'trailing comma'
    elif msg.startswith('Extra data'):
        m = 'trailing characters'
    elif msg.startswith('Unterminated string'):
        m = 'EOF while parsing a string'
        pos = len(text)
    elif msg.startswith('Invalid control'):
        m = 'control character (\\u0000-\\u001F) found while parsing a string'
    elif msg.startswith('Invalid \\escape'):
        m = 'invalid escape'
    elif pos >= len(text):
        m = 'EOF while parsing an object' if text.rstrip().endswith(('{', ',')) else 'EOF while parsing a value'
    elif msg.startswith("Expecting ':'"):
        m = "expected `:`"
    elif msg.startswith("Expecting ','"):
        m = "expected `,` or `}`" if text.lstrip().startswith('{') else "expected `,` or `]`"
    else:
        m = 'expected value'
    line = text.count('\n',0,pos)+1
    col = pos - text.rfind('\n',0,pos) if pos<len(text) else pos - text.rfind('\n',0,pos)-1
    return f'{m} at line {line} column {col}'

def load_json_text(text):
    try:
        return json.loads(text)
    except json.JSONDecodeError as e:
        raise Failure(json_error(e, text))

def pretty(data, newline=True):
    return json.dumps(data, indent=2, ensure_ascii=False) + ('\n' if newline else '')

def location(text, pos=None):
    if pos is None:
        pos = len(text.rstrip())
    return f'at line {text.count(chr(10),0,pos)+1} column {pos-text.rfind(chr(10),0,pos)-1}'

def typedescr(v):
    if v is None: return 'null'
    if v is True or v is False: return 'boolean `' + str(v).lower() + '`'
    if isinstance(v, str): return 'string ' + json.dumps(v,ensure_ascii=False)
    if isinstance(v, int): return 'integer `' + str(v) + '`'
    if isinstance(v, float): return 'floating point `' + str(v) + '`'
    if isinstance(v,list): return 'sequence'
    return 'map'
