"""Configuration discovery and grammar repository metadata."""
import json
import os
from pathlib import Path
from common import Failure, err, warning, resource, pretty, os_error, load_json_text, typedescr, location

CONFIG_WARNING = 'You have not configured any parser directories!\nPlease run `tree-sitter init-config` and edit the resulting\nconfiguration file to indicate where we should look for\nlanguage grammars.\n'

def config_path():
    home=os.environ.get('HOME',str(Path.home()))
    xdg=os.environ.get('XDG_CONFIG_HOME')
    return Path(xdg if xdg and os.path.isabs(xdg) else os.path.join(home,'.config'))/'tree-sitter/config.json'

def initial_config():
    p=config_path()
    if p.exists():raise Failure('Remove your existing config file first: '+str(p))
    home=os.environ.get('HOME',str(Path.home()))
    data={'parser-directories':[os.path.join(home,d) for d in ['github','src','source','projects','dev','git']], 'theme':json.loads(resource('theme.json'))}
    try:
        p.parent.mkdir(parents=True,exist_ok=True)
        p.write_text(pretty(data,newline=False))
    except OSError as e:raise Failure(os_error(e))
