def read_config(opts, warn=True):
    p=Path(opts.get('config-path',config_path()))
    cfg={}
    try:text=p.read_text()
    except OSError as e:
        if 'config-path' in opts or e.errno != 2:raise Failure(os_error(e)+' ('+str(p)+')')
    else:
