#!/usr/bin/env python3
"""Entry point for the independent parser CLI implementation."""
import os
import sys
from common import Failure, out, report_failure, os_error
from arguments import parse

def main():
    try:
        cmd,opts,args=parse(sys.argv[1:])
        if cmd=='help':out(opts['text'])
        elif cmd=='complete':
            from common import resource
            out(resource('completions/complete-'+opts['shell']+'.txt'))
        elif cmd in ('init-config','dump-languages'):
            from configuration import initial_config,dump_languages
            if cmd=='init-config':initial_config()
            else:dump_languages(opts)
        elif cmd in ('init','version'):
            from repository import initialize,version
            if cmd=='init':initialize(opts)
            else:version(opts,args)
        elif cmd in ('generate','build'):
            from grammar import generate,build
            (generate if cmd=='generate' else build)(opts,args)
        elif cmd=='parse':
            from commands import parse_command
            parse_command(opts,args)
        elif cmd in ('test','fuzz'):
            from commands import test_command
            test_command(opts,args,cmd=='fuzz')
        elif cmd in ('query','highlight','tags'):
            from queries import query_command,highlight_command,tags_command
            {'query':query_command,'highlight':highlight_command,'tags':tags_command}[cmd](opts,args)
        elif cmd=='playground':
            from playground import playground
            playground(opts)
        return 0
    except Failure as e:
        report_failure(e);return e.code
    except BrokenPipeError:return 0
    except OSError as e:
        report_failure(Failure(os_error(e)));return 1
    except KeyboardInterrupt:return 130

if __name__=='__main__':
    sys.exit(main())
