        if kind=='node':message=prefix+'Invalid node type '+json.dumps(value)
        elif kind=='field':message=prefix+'Invalid field name '+json.dumps(value)
        elif kind=='capture':message=prefix+'Invalid capture name '+json.dumps(value)
        else:
            lines=self.text.splitlines();line=lines[row] if row<len(lines) else ''
